harness_sources.build_trace.py:
"""Build a replayable per-page yield trace from one stored ECDEV crawl run.
python -I build_trace.py <engine root> <helper binary> <site> <out.json>
Reads the crawl database (fetch order, parent, depth, state) and each fetched page's stored raw capture,
re-extracts it with ECDEV's own extractor (helper `trace`) and records, per fetched page, the components of
information yield. Nothing is requested from the site."""
import json, sqlite3, subprocess, sys, urllib.parse, re, collections
root, helper, site, out = sys.argv[1:5]
db = sqlite3.connect(f"{root}/.ecdev-data/runtime/ecdev.sqlite")
urls = {r[0]: r for r in db.execute("select canonical_url,source_page,depth,state,payload,last_error,identity_hash from crawl_urls")}
by_hash = {r[6]: r[0] for r in urls.values()}
# fetch order: terminal events in event order
order = []
seen = set()
for _id, h, state, reason in db.execute("select id,identity_hash,state,reason from crawl_events order by id"):
    if state in ("HANDLED", "FAILED") and h not in seen:
        seen.add(h); order.append((h, state, reason))
children = collections.defaultdict(list)
for u, r in urls.items():
    if r[1]: children[r[1]].append(u)
SCALAR_SKIP = {"kind", "canonical_url", "price_status", "sales_status", "page_relation", "relation", "provenance", "price_source", "title_source", "variants"}
IDK = ["gtin14", "gtin13", "gtin12", "gtin8", "gtin", "ean", "upc", "jan", "isbn"]
def ident(p, page):
    for k in IDK:
        if p.get(k): return "gtin:" + str(p[k])
    if p.get("mpn"): return "mpn:" + str(p.get("brand") or "") + ":" + str(p["mpn"])
    host = urllib.parse.urlsplit(page).netloc
    if p.get("sku"): return "sku:" + host + ":" + str(p["sku"])
    if p.get("canonical_url"): return "url:" + p["canonical_url"]
    return "title:" + host + ":" + str(p.get("title"))
def shape(u):
    s = urllib.parse.urlsplit(u)
    segs = [x for x in s.path.split("/") if x]
    g = []
    for x in segs:
        if re.fullmatch(r"\d+", x): g.append("#")
        elif re.fullmatch(r"[0-9a-fA-F-]{8,}", x): g.append("#")
        elif re.search(r"\d", x) and len(x) > 6: g.append("~id")
        else: g.append(x if len(g) < 1 else "*")
    q = sorted({k for k, _ in urllib.parse.parse_qsl(s.query)})
    return "/" + "/".join(g) + ("?" + "&".join(q) if q else "")
rows = []
cum_ident = {}; cum_list = {}; cum_fields = set(); cum_assert = set(); vals = collections.defaultdict(set); conflicts = set()
for ordinal, (h, state, reason) in enumerate(order, 1):
    u = by_hash[h]; r = urls[u]
    row = {"ordinal": ordinal, "url": u, "parent": r[1], "depth": r[2], "shape": shape(u), "state": state, "reason": reason}
    kids = children.get(u, [])
    row["children_admitted"] = len(kids)
    row["children_refused_by_policy"] = sum(1 for k in kids if (urls[k][5] or "").startswith("ROBOTS"))
    if state != "HANDLED":
        row["fetched"] = reason not in ("ROBOTS_DENIED_OR_UNKNOWN", "ROBOTS_REFUSES_AI_AGENTS")
        rows.append(row); continue
    row["fetched"] = True
    pl = json.loads(r[4]); cap = pl["capture"]
    ch = cap["result"].get("content_hash") or next((o.get("raw_hash") for o in cap.get("observations", []) if o.get("raw_hash")), None)
    import os
    if not ch or not os.path.exists(f"{root}/.ecdev-data/raw/{ch}.html"):
        row["role"] = "NO_RAW_CAPTURE"; row["result_keys"] = sorted(cap["result"])[:8]; rows.append(row); continue
    t = json.loads(subprocess.check_output([helper, "trace", f"{root}/.ecdev-data/raw/{ch}.html", "text/html", u]))
    row["raw_capture_sha256"] = ch
    prods = t.get("products", []) if t.get("ok") else []
    links = t.get("links", []) if t.get("ok") else []
    own = [p for p in prods if (p.get("page_relation") or {}).get("relation", p.get("relation")) in ("PAGE_SUBJECT", "PAGE_SUBJECT_VARIANT", "NOT_STATED", None)]
    row["links_out"] = len(set(links)); row["products_extracted"] = len(prods); row["own_products"] = len(own)
    row["role"] = "PRODUCT" if own else ("LISTING" if prods else "OTHER")
    new_id = new_idb = enrich_fields = new_assert = new_conf = 0
    touched = set()
    for p in own:
        i = ident(p, u)
        is_new = i not in cum_ident
        if is_new:
            cum_ident[i] = {"first": ordinal, "idb": i.startswith(("gtin:", "mpn:"))}
            new_id += 1; new_idb += cum_ident[i]["idb"]
        touched.add(i)
        for k, v in p.items():
            if k in SCALAR_SKIP or v is None or isinstance(v, (dict, list)) or v == "": continue
            if k not in ("title", "brand", "price_minor", "currency", "availability", "sku", "mpn", "ean", "category", "color", "description", "image", "rating", "review_count", "seller", "weight_g") and not k.startswith("gtin"): continue
            if (i, k) not in cum_fields:
                cum_fields.add((i, k))
                if not is_new: enrich_fields += 1
            a = (i, k, json.dumps(v, sort_keys=True))
            if a not in cum_assert:
                cum_assert.add(a); new_assert += 1
                vals[(i, k)].add(a[2])
                if len(vals[(i, k)]) == 2: conflicts.add((i, k)); new_conf += 1
    others = [p for p in prods if p not in own]
    new_list = 0
    for p in others:
        i = ident(p, p.get("canonical_url") or u)
        if i not in cum_ident and i not in cum_list:
            cum_list[i] = ordinal; new_list += 1
    row["new_listing_identities"] = new_list; row["cum_listing_identities"] = len(cum_list)
    row["new_identities"] = new_id; row["new_identifier_bearing"] = new_idb
    row["new_fields_on_known"] = enrich_fields; row["new_assertions"] = new_assert; row["new_conflicts"] = new_conf
    row["enriched_known"] = (not new_id) and (enrich_fields > 0)
    row["cum_identities"] = len(cum_ident); row["cum_fields"] = len(cum_fields); row["cum_assertions"] = len(cum_assert); row["cum_conflicts"] = len(conflicts)
    rows.append(row)
json.dump({"site": site, "pages": rows, "identities": cum_ident}, open(out, "w"), indent=0)
fetched = [r for r in rows if r.get("fetched")]
print(site, "fetched", len(fetched), "handled", sum(r["state"] == "HANDLED" for r in rows), "identities", len(cum_ident), "roles", dict(collections.Counter(r.get("role") for r in rows if r["state"] == "HANDLED")))

harness_sources.replay.py:
"""Offline replay of early-stop and path-scope policies on captured per-page yield traces.
python -I replay.py <out.json> <trace.json>...
No network. The full bounded trace is the baseline, never the catalogue total."""
import json, sys, collections, itertools
out = sys.argv[1]
T = {}
for f in sys.argv[2:]:
    d = json.load(open(f)); T[d["site"]] = d
def pages(d): return [r for r in d["pages"] if r.get("fetched")]
def low(r): return r.get("role") is None or (r.get("new_identities", 0) + r.get("new_fields_on_known", 0) + r.get("new_listing_identities", 0)) == 0
def totals(rows):
    ids = set(); idb = 0; fields = 0; assertions = 0; conflicts = 0
    return {"identities": sum(r.get("new_identities", 0) for r in rows), "listing_identities": sum(r.get("new_listing_identities", 0) for r in rows), "identifier_bearing": sum(r.get("new_identifier_bearing", 0) for r in rows),
            "enrichment_fields": sum(r.get("new_fields_on_known", 0) for r in rows), "assertions": sum(r.get("new_assertions", 0) for r in rows), "conflicts": sum(r.get("new_conflicts", 0) for r in rows)}
def metrics(d, kept_ordinals):
    P = pages(d); kept = [r for r in P if r["ordinal"] in kept_ordinals]
    full, got = totals(P), totals(kept)
    n = len(P); k = len(kept)
    last_q = P[int(n * 0.75):]
    late_full = totals(last_q)["identities"]; late_got = totals([r for r in last_q if r["ordinal"] in kept_ordinals])["identities"]
    m = {"pages": n, "pages_kept": k, "saved_pages": n - k, "saved_frac": round((n - k) / n, 4) if n else 0.0}
    for key in full:
        m[key + "_full"] = full[key]; m[key + "_kept"] = got[key]
        m[key + "_missed_frac"] = round(1 - got[key] / full[key], 4) if full[key] else None
    m["late_identities_full"] = late_full; m["late_identities_lost"] = late_full - late_got
    return m
def consec(d, N):
    """stop the whole crawl after N consecutive fetched pages with no new identity and no new field"""
    kept = set(); run = 0
    for r in pages(d):
        kept.add(r["ordinal"])
        run = run + 1 if low(r) else 0
        if run >= N: break
    return kept
def window(d, W, tau):
    """stop when new identities in the last W fetched pages <= tau (after at least W pages)"""
    kept = set(); hist = []
    for r in pages(d):
        kept.add(r["ordinal"]); hist.append(r.get("new_identities", 0) + r.get("new_listing_identities", 0))
        if len(hist) >= W and sum(hist[-W:]) <= tau: break
    return kept
def region(d, N, minpages=0):
    """per path-shape: after N consecutive zero-yield pages in that shape, skip the shape's later pages and their descendants"""
    P = pages(d); kept = set(); run = collections.Counter(); closed = set(); skipped_urls = set()
    for r in P:
        if r["shape"] in closed or r["parent"] in skipped_urls:
            skipped_urls.add(r["url"]); continue
        kept.add(r["ordinal"])
        run[r["shape"]] = run[r["shape"]] + 1 if low(r) else 0
        if run[r["shape"]] >= N: closed.add(r["shape"])
    return kept
def both(d, N, W):
    kept = set(); run = 0; hist = []
    for r in pages(d):
        kept.add(r["ordinal"]); hist.append(r.get("new_identities", 0) + r.get("new_listing_identities", 0))
        run = run + 1 if low(r) else 0
        if run >= N and len(hist) >= W and sum(hist[-W:]) == 0: break
    return kept
def subtree_adaptive(d, k):
    """per path-shape, online: close a shape once k of its pages were fetched and neither they nor any page
    below them has yielded a new identity or field so far (subtree yield, not page yield); skip its later pages
    and their descendants."""
    P = pages(d); kept = set(); fetched = collections.Counter(); sub = collections.Counter(); closed = set(); skipped = set()
    shape_of = {r["url"]: r["shape"] for r in P}; parent = {r["url"]: r["parent"] for r in P}
    for r in P:
        if r["shape"] in closed or r["parent"] in skipped:
            skipped.add(r["url"]); continue
        kept.add(r["ordinal"]); fetched[r["shape"]] += 1
        y = r.get("new_identities", 0) + r.get("new_fields_on_known", 0) + r.get("new_listing_identities", 0)
        if y:
            u = r["url"]; seen = set()
            while u is not None and u not in seen:
                seen.add(u)
                if u in shape_of: sub[shape_of[u]] += y
                u = parent.get(u)
        for sh in list(fetched):
            if sh not in closed and fetched[sh] >= k and sub[sh] == 0: closed.add(sh)
    return kept
GRID = [("consecutive_low", {"N": N}, lambda d, p: consec(d, p["N"])) for N in (3, 5, 8, 12, 20, 30)] + \
       [("rolling_identity_window", {"W": W, "tau": 0}, lambda d, p: window(d, p["W"], p["tau"])) for W in (10, 20, 30, 40)] + \
       [("region_consecutive_low", {"N": N}, lambda d, p: region(d, p["N"])) for N in (2, 3, 5, 8, 12)] + \
       [("region_subtree_adaptive", {"k": k}, lambda d, p: subtree_adaptive(d, p["k"])) for k in (2, 3, 5, 8, 12)] + \
       [("identity_and_enrichment_low", {"N": N, "W": W}, lambda d, p: both(d, p["N"], p["W"])) for N in (5, 10) for W in (20, 40)]
res = {}
for site, d in T.items():
    res[site] = {"trace": {"fetched_pages": len(pages(d)), **totals(pages(d))}, "policies": []}
    for name, params, fn in GRID:
        kept = fn(d, params)
        res[site]["policies"].append({"policy": name, "params": params, **metrics(d, kept)})
# leave-one-catalogue-out: pick, on the other sites with identities, the policy with the largest mean saved fraction
# whose worst missed-identity fraction is <= EPS; evaluate it on the held-out site.
EPS = 0.02
def key(p): return (p["policy"], json.dumps(p["params"], sort_keys=True))
loo = []
sites = [s for s in T if res[s]["trace"]["identities"] + res[s]["trace"]["listing_identities"] > 0]
for held in T:
    train = [s for s in sites if s != held]
    cand = collections.defaultdict(list)
    for s in train:
        for p in res[s]["policies"]: cand[key(p)].append(p)
    best = None
    for k, ps in cand.items():
        worst = max(max((p["identities_missed_frac"] or 0), (p["listing_identities_missed_frac"] or 0)) for p in ps)
        mean_saved = sum(p["saved_frac"] for p in ps) / len(ps)
        if worst <= EPS and (best is None or mean_saved > best[0]): best = (mean_saved, k, worst)
    row = {"held_out": held, "train_sites": train, "eps_max_missed_identity_fraction": EPS}
    if best is None:
        row["chosen"] = None; row["note"] = "no policy kept missed identities within EPS on every training site"
    else:
        k = best[1]; row["chosen"] = {"policy": k[0], "params": json.loads(k[1]), "train_mean_saved": round(best[0], 4), "train_worst_missed": best[2]}
        hp = next(p for p in res[held]["policies"] if key(p) == k)
        row["held_out_result"] = hp
    loo.append(row)
json.dump({"sites": res, "leave_one_catalogue_out": loo, "grid_size": len(GRID)}, open(out, "w"), indent=1)
for s, v in res.items(): print(s, v["trace"])
print("--- no-lose policies per site (missed identities == 0 and saved>0):")
for s, v in res.items():
    ok = [(p["policy"], p["params"], p["saved_frac"]) for p in v["policies"] if (p["identities_missed_frac"] in (0, 0.0, None)) and (p["listing_identities_missed_frac"] in (0, 0.0, None)) and p["saved_frac"] > 0]
    print(s, len(ok), sorted(ok, key=lambda x: -x[2])[:3])
print("--- LOO:")
for r in loo: print(r["held_out"], r.get("chosen"), (r.get("held_out_result") or {}).get("saved_frac"), (r.get("held_out_result") or {}).get("identities_missed_frac"))

harness_sources.scope.py:
"""Path/query-shape productivity and subtree yield on captured traces; offline exclusion-rule evaluation.
python -I scope.py <out.json> <trace.json>..."""
import json, sys, collections
out = sys.argv[1]
T = {}
for f in sys.argv[2:]:
    d = json.load(open(f)); T[d["site"]] = d
def yld(r): return r.get("new_identities", 0) + r.get("new_fields_on_known", 0) + r.get("new_listing_identities", 0)
res = {}
for site, d in T.items():
    P = [r for r in d["pages"] if r.get("fetched")]
    allrows = d["pages"]
    parent = {r["url"]: r["parent"] for r in P}
    shape = {r["url"]: r["shape"] for r in P}
    g = collections.defaultdict(lambda: collections.Counter())
    sub = collections.Counter(); subpages = collections.Counter()
    for r in P:
        s = r["shape"]; g[s]["fetched"] += 1
        g[s]["product_pages"] += r.get("role") == "PRODUCT"; g[s]["listing_pages"] += r.get("role") == "LISTING"
        g[s]["own_new_identities"] += r.get("new_identities", 0); g[s]["new_listing_identities"] += r.get("new_listing_identities", 0)
        g[s]["errors"] += r.get("state") != "HANDLED"
        g[s]["children_admitted"] += r.get("children_admitted", 0)
        y = yld(r)
        # credit every ancestor shape (once per shape per page chain) with the yield: subtree yield
        u = r["url"]; seen = set(); chain = set()
        while u is not None and u not in seen:
            seen.add(u)
            if u in shape: chain.add(shape[u])
            u = parent.get(u)
        for sh in chain:
            sub[sh] += y; subpages[sh] += 1
    refused = collections.Counter()
    for r in allrows:
        if r.get("reason", "") and str(r["reason"]).startswith("ROBOTS"): refused[r["shape"]] += 1
    groups = []
    for sh, c in g.items():
        groups.append({"shape": sh, **c, "page_yield": c["own_new_identities"] + c["new_listing_identities"], "subtree_yield": sub[sh], "subtree_pages": subpages[sh], "policy_refused_children_seen": 0})
    groups.sort(key=lambda x: -x["fetched"])
    # exclusion rule evaluation: exclude shape G (never fetch it nor anything beneath it)
    rules = []
    total_y = sum(yld(r) for r in P)
    for gr in groups:
        lost_pages = gr["subtree_pages"]; lost_y = gr["subtree_yield"]
        rules.append({"exclude_shape": gr["shape"], "pages_not_fetched": lost_pages, "pages_frac": round(lost_pages / len(P), 4), "yield_lost": lost_y, "yield_lost_frac": round(lost_y / total_y, 4) if total_y else None, "page_yield_of_group": gr["page_yield"], "subtree_yield_of_group": gr["subtree_yield"]})
    res[site] = {"fetched": len(P), "total_yield": total_y, "policy_refused_urls": dict(refused), "groups": groups[:25], "exclusion_rules": [r for r in rules if r["pages_frac"] >= 0.03][:25]}
json.dump(res, open(out, "w"), indent=1)
for site, v in res.items():
    print("==", site, "fetched", v["fetched"], "total_yield", v["total_yield"])
    for gr in v["groups"][:8]:
        print("  %-38s fetched=%-3d prod=%-3d list=%-3d pageY=%-5d subtreeY=%-5d" % (gr["shape"][:38], gr["fetched"], gr["product_pages"], gr["listing_pages"], gr["page_yield"], gr["subtree_yield"]))
